import{_ as t,o,c as r,a2 as e}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"审批与信任","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/approvals.md","filePath":"zh/guides/approvals.md","lastUpdated":1790952322000}'),l={name:"zh/guides/approvals.md"};function s(i,a,n,h,p,c){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="审批与信任" tabindex="-1">审批与信任 <a class="header-anchor" href="#审批与信任" aria-label="Permalink to &quot;审批与信任&quot;">​</a></h1><p>一个能写文件、能执行命令、能给人发消息的 Bot，需要一条你真正理解的边界。这一页从使用者的角度讲清这条边界：Bot 够得着什么、什么时候会停下来问、审批管得住什么又管不住什么。具体机制——成员列表、模式、规则——在 <a href="./access.html">访问控制</a>。</p><h2 id="bot-默认能碰什么" tabindex="-1">Bot 默认能碰什么 <a class="header-anchor" href="#bot-默认能碰什么" aria-label="Permalink to &quot;Bot 默认能碰什么&quot;">​</a></h2><ul><li><strong>自己的工作区，仅此而已。</strong> 每个 Bot 在自己隔离的容器工作区（<code>/data</code>）里干活。文件和状态都留在里面，Bot 之间互相看不见——见 <a href="./container.html">工作区</a>。</li><li><strong>只有你接入的渠道和授权的人。</strong> Bot 能出现在某个平台，是因为你在 <strong>平台</strong> 标签页添加了它；能回应某个身份，是因为访问控制放行了。</li><li><strong>每个人只有被授予的那一级。</strong> 工作区权限分五级：聊天、读文件、写文件、执行命令、管理；任务需要哪级给哪级，不多给。级别定义见 <a href="./access.html">访问控制</a>。</li></ul><p>这些授权来自 Bot <strong>Access</strong> 标签页上的两份成员列表：<strong>渠道成员</strong> 管 IM 平台上的身份，<strong>工作区成员</strong> 管 Memoh 注册用户。</p><h2 id="什么时候会来问你" tabindex="-1">什么时候会来问你 <a class="header-anchor" href="#什么时候会来问你" aria-label="Permalink to &quot;什么时候会来问你&quot;">​</a></h2><p>写入和执行类工具调用可以要求人工批准，按 Bot 在 <strong>Tool Approval</strong> 标签页里配置。一个工具被设为需要确认时，流程是：</p><ol><li>Bot 提出这个动作——具体到某一次工具调用，此时什么都还没执行。</li><li>你批准或拒绝。</li><li>只有批准的调用才会执行；被拒绝的永远不会跑。</li></ol><p>审批永远发生在动作之前，所以审一眼请求就是控制权本身，而不是事后补救。等待中的请求也可能超时，不会无限等下去；错过了就让 Bot 把这个动作再试一次。</p><div class="tip custom-block"><p class="custom-block-title">想加更多关卡也可以</p><p>在 Tool Approval 设置之外，命中某个事件的 <a href="./hooks.html">Hook</a> 也能主动发起人工审批——适合只看住某一类命令，而不是拦下整个工具。</p></div><h2 id="建议留在审批后面的动作" tabindex="-1">建议留在审批后面的动作 <a class="header-anchor" href="#建议留在审批后面的动作" aria-label="Permalink to &quot;建议留在审批后面的动作&quot;">​</a></h2><p>以下是建议，不是 Memoh 强制的默认值；当作一份稳妥的起步清单：</p><ul><li><strong>会离开工作区的消息</strong>——发给其他人或公开发布的任何内容。</li><li><strong>删除或覆盖文件</strong>，尤其是不是 Bot 自己建的那些。</li><li><strong>在工作区里执行安装和长时间运行的命令。</strong></li><li><strong>任何花钱或触碰生产环境的动作。</strong></li></ul><p>留在 Bot 自己工作区之内的动作（起草、整理、阅读）最先值得放出审批。这份建议怎么嵌进一个流程的生命周期，从第一次只读运行到逐步放宽，见 <a href="./working-with-bots.html">和 Bot 协作</a>。</p><h2 id="桌面接管与凭据" tabindex="-1">桌面接管与凭据 <a class="header-anchor" href="#桌面接管与凭据" aria-label="Permalink to &quot;桌面接管与凭据&quot;">​</a></h2><p>Bot 在可视化桌面里干活时撞上登录墙或验证码，就由你接管屏幕，亲手输入密码、通行密钥或一次性验证码，然后把控制权交还。凭据从你的键盘直接进网站——你从头到尾不需要把它告诉 Bot。</p><p>之后浏览器会话留在该工作区里，后续任务保持登录状态，不用再接管一次。见 <a href="./browser-computer-use.html">浏览器 / 电脑操作</a> 与 <a href="./quick-start.html#第-5-步-让它用上工作区和浏览器">快速开始</a>。</p><h2 id="一条诚实的边界说明" tabindex="-1">一条诚实的边界说明 <a class="header-anchor" href="#一条诚实的边界说明" aria-label="Permalink to &quot;一条诚实的边界说明&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">审批管不住的部分</p><p>审批拦的是「提议中的动作」——它不能撤销已经执行的工作，也收不回已经发出去的消息。拒绝一个请求只是拦下这一个请求，它不是回滚按钮。</p></div><p>所以真正持久的习惯还是 <a href="./access.html">访问控制</a> 里那条：按任务给最低级别，检查几次运行，再逐步放宽。对 Bot 的信任和对新同事的信任是同一种东西：靠证据一点点建立。</p>',20)])])}const g=t(l,[["render",s]]);export{u as __pageData,g as default};
